package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result);
    }

    @Test
    public void testParseOctal_WithTrailingNulsAndSpaces() {
        // The logic: trailer = buffer[end-0]. If trailer is 0 or ' ', end--.
        // Note: The provided code has a potential IndexOutOfBounds if end is 0, 
        // but based on length >= 2 requirement, end is at least 2.
        byte[] buffer = "0123  \0\0".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(66L, result);
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_OffsetHandling() {
        byte[] buffer = "abc 010 def".getBytes();
        // offset 4, length 3 -> "010"
        long result = TarUtils.parseOctal(buffer, 4, 3);
        assertEquals(8L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharacters() {
        byte[] buffer = "0128".getBytes(); // 8 is not octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidCharactersAlpha() {
        byte[] buffer = "012A".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max long octal scenario (though limited by byte array size)
        byte[] buffer = "7777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 10);
        assertEquals(536870911L, result);
    }

    @Test
    public void testParseOctal_TrailingSpaceOnly() {
        byte[] buffer = "012 ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_MixedTrailing() {
        // Testing the loop: trailer == 0 || trailer == ' '
        byte[] buffer = "012 \0 ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_StartWithSpaceButNotZero() {
        byte[] buffer = "  012".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_BufferStartZeroWithOffset() {
        byte[] buffer = new byte[]{0, 0, 0, '0', '1'};
        // If buffer[start] == 0, returns 0 immediately
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 3));
        // If buffer[start] != 0
        assertEquals(1L, TarUtils.parseOctal(buffer, 3, 2));
    }
}
